    def build(q, posts, gap, ptop=0.2):
        t = rng.randint(0, 100)
        lines = []
        for _ in range(q):
            t += rng.randint(0, gap)
            if rng.random() < ptop:
                lines.append(f'TOP {t}')
            else:
                lines.append(f'ACTION {rng.randint(1, posts)} {rng.choice(kinds)} {t}')
        return str(q) + '\n' + '\n'.join(lines)
